# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::MoneySnapshotFile do
  # "A resumed run, including a restart after step 4 was recorded, then compares against the same snapshot"
  # A lossy file would make every resumed run report a money change, or hide a real one.
  it "round-trips a two-company money snapshot without losing decimals, types or symbol keys" do
    snapshots = {
      11 => {
        company_id: 11,
        values: {
          [:invoice, 501, :amount] => BigDecimal("0.1000000000000000001"),
          [:invoice, 501, :status_code] => 3,
          [:invoice, 501, :currency] => "USD",
          [:invoice, 501, :discount] => nil
        }
      }.freeze,
      12 => {
        company_id: 12,
        values: { [:payment, 9, :amount] => BigDecimal("1234567890.12") }
      }.freeze
    }

    loaded = described_class.load(described_class.dump(snapshots))

    expect(loaded.keys).to contain_exactly(11, 12)
    expect(loaded.fetch(11)).to eq(snapshots.fetch(11))
    expect(loaded.fetch(12)).to eq(snapshots.fetch(12))
    expect(loaded.fetch(11)[:values][[:invoice, 501, :amount]]).to be_a(BigDecimal)
    expect(loaded.fetch(11)[:values][[:invoice, 501, :status_code]]).to be_a(Integer)
  end
end

RSpec.describe Timekeeping::Handoff::MoneySnapshotFile do
  # "Money: take `FinancialSnapshot.take(company_id:)` for every company at the end of step 2, and again
  # after step 6, and pass both to reconciliation."
  # Two tenants with the same invoice ids and fields must come back apart: a format that merged or summed
  # them would let one company's change hide behind the other's.
  it "keeps each company's money under its own company id when two companies share the same value keys" do
    snapshots = {
      101 => {
        company_id: 101,
        values: {
          [:invoice, 9, :amount] => BigDecimal("120.10"),
          [:invoice, 9, :status] => "sent",
          [:payment, 3, :amount] => nil
        }
      },
      202 => {
        company_id: 202,
        values: {
          [:invoice, 9, :amount] => BigDecimal("0.1000000000000000001"),
          [:invoice, 9, :status] => "draft",
          [:payment, 3, :amount] => 7
        }
      }
    }

    loaded = described_class.load(described_class.dump(snapshots))

    expect(loaded.keys).to contain_exactly(101, 202)
    expect(loaded[101]).to eq(snapshots[101])
    expect(loaded[202]).to eq(snapshots[202])
    expect(loaded[101][:values][[:invoice, 9, :amount]]).to eq(BigDecimal("120.10"))
    expect(loaded[202][:values][[:invoice, 9, :amount]]).to eq(BigDecimal("0.1000000000000000001"))
  end
end

RSpec.describe Timekeeping::Handoff::MoneySnapshotFile do
  it "round-trips a two-company money snapshot with exact decimals, nils and symbol-array keys" do
    # "A resumed run, including a restart after step 4 was recorded, then compares against the same snapshot"
    snapshots = {
      11 => { company_id: 11, values: {
        [:invoice, 5, :amount] => BigDecimal("0.1000000000000000001"),
        [:invoice, 5, :status] => "sent",
        [:payment, 7, :cents] => 0,
        [:invoice, 5, :discount] => nil
      } },
      12 => { company_id: 12, values: { [:invoice, 9, :amount] => BigDecimal("1250.50") } }
    }

    loaded = described_class.load(described_class.dump(snapshots))

    expect(loaded).to eq(snapshots)
    expect(loaded.keys).to all(be_a(Integer))
    expect(loaded[11][:values][[:invoice, 5, :amount]]).to be_a(BigDecimal)
    expect(loaded[11][:values][[:invoice, 5, :amount]].to_s("F")).to eq("0.1000000000000000001")
    expect(loaded[11][:values][[:payment, 7, :cents]]).to be_a(Integer)
    expect(loaded[11][:values]).to have_key([:invoice, 5, :discount])
  end
end

RSpec.describe Timekeeping::Handoff::MoneySnapshotFile do
  it "reads back a snapshot that FinancialSnapshot.compare finds unchanged, with string company ids as integers" do
    snapshot = {
      company_id: 31,
      values: {
        [:invoice, 4, :amount] => BigDecimal("99.990"),
        [:pdf_total, 4, :total] => BigDecimal("0.1000000000000000001"),
        [:invoice_tax, 8, :name] => "VAT",
        [:invoice, 4, :discount] => nil
      }
    }.freeze

    loaded = described_class.load(described_class.dump({ "31" => snapshot }))

    expect(loaded.keys).to eq([31])
    expect(Timekeeping::FinancialSnapshot.compare(snapshot, loaded.fetch(31))).to eq([])
  end

  it "refuses text that is not a snapshot file with its own error" do
    expect { described_class.load('{"companies": [{"company_id": 1') }
      .to raise_error(described_class::Unreadable)
    expect { described_class.load('{"other": []}') }.to raise_error(described_class::Unreadable)
  end
end
